// Clase 11: validar formato Y límites de la solicitud antes de tocar cualquier fuente.
const body = $json.body ?? {};
const errores = [];

if (body.accion !== 'revisar_stock') {
  errores.push('El campo accion debe ser revisar_stock');
}

const id = typeof body.solicitud_id === 'string' ? body.solicitud_id.trim() : '';
if (id === '') {
  errores.push('Falta el campo obligatorio solicitud_id');
} else if (id.length > 64 || !/^[A-Za-z0-9_.-]+$/.test(id)) {
  errores.push('solicitud_id solo admite letras, números, punto, guion y guion bajo (máximo 64 caracteres)');
}

return [{
  json: {
    valido: errores.length === 0,
    errores,
    accion: body.accion ?? null,
    solicitud_id: id || null
  }
}];

// Clase 11: calidad de la fuente. Formato y significado: números reales, no negativos, campos completos.
const num = v => (v === '' || v === null || v === undefined) ? NaN : Number(v);
const txt = v => (v === null || v === undefined) ? '' : String(v).trim();
const salida = [];
for (const item of $input.all()) {
  const f = item.json;
  const motivos = [];
  const producto = txt(f.producto);
  const categoria = txt(f.categoria);
  const cantidad = num(f.cantidad);
  const stock_minimo = num(f.stock_minimo);

  if (!producto) motivos.push('producto vacío');
  if (!categoria) motivos.push('categoria vacía');
  if (!Number.isFinite(cantidad) || cantidad < 0) motivos.push('cantidad ausente, no numérica o negativa');
  if (!Number.isFinite(stock_minimo) || stock_minimo < 0) motivos.push('stock_minimo ausente, no numérico o negativo');

  salida.push({ json: {
    ...f, producto, categoria,
    cantidad: Number.isFinite(cantidad) ? cantidad : null,
    stock_minimo: Number.isFinite(stock_minimo) ? stock_minimo : null,
    observacion: txt(f.observacion),
    dato_valido: motivos.length === 0,
    motivos_invalidos: motivos.join('; '),
    fila_original: f.row_number ?? 'N/A'
  } });
}
return salida;

// Clase 11: la respuesta final debe coincidir con lo que realmente ocurrió, producto por producto.
const j = $json;
const fallo = j.error !== undefined && j.error !== null && j.error !== '';
return { json: {
  resultado: fallo ? 'fallo' : (j.resultado ?? 'sin_resultado'),
  producto: j.producto ?? null,
  detalle: fallo ? String(j.error?.message ?? j.error) : null
} };

// Resumen real de la ejecución (no un texto fijo). Se usa también cuando no hay productos bajo el mínimo.
const res = $input.all().map(i => i.json).filter(j => j.resultado !== undefined);

let solicitud_id = 'manual-prueba';
try { solicitud_id = $('Validar Solicitud').first().json.solicitud_id; }
catch (e) {
  try { $('Schedule Trigger Diario').first(); solicitud_id = 'programado-diario'; } catch (e2) {}
}

const cuenta = r => res.filter(x => x.resultado === r).length;
const fallidas = cuenta('fallo');
const creadas = cuenta('creada');
const omitidas = cuenta('duplicado_omitido');
const filas_invalidas = $('Validar Datos Inventario').all().filter(i => i.json.dato_valido === false).length;

return [{ json: {
  ok: fallidas === 0,
  estado: fallidas === 0 ? 'completado' : 'completado_con_fallos',
  solicitud_id,
  productos_bajo_minimo: res.length,
  alertas_creadas: creadas,
  duplicados_omitidos: omitidas,
  alertas_fallidas: fallidas,
  filas_invalidas,
  mensaje: 'Revisión de inventario completada: ' + creadas + ' alerta(s) creada(s), ' + omitidas +
           ' duplicada(s) omitida(s), ' + fallidas + ' con fallo, ' + filas_invalidas + ' fila(s) inválida(s).'
} }];

// Clase 11: la subetapa también valida lo que recibe (puede llamarse de forma independiente).
const j = $json;
const errores = [];
const producto = typeof j.producto === 'string' ? j.producto.trim() : '';
const categoria = typeof j.categoria === 'string' ? j.categoria.trim() : '';
const num = v => (v === '' || v === null || v === undefined) ? NaN : Number(v);
const cantidad = num(j.cantidad);
const stock_minimo = num(j.stock_minimo);

if (!producto) errores.push('producto vacío');
if (!categoria) errores.push('categoria vacía');
if (!Number.isFinite(cantidad) || cantidad < 0) errores.push('cantidad no válida');
if (!Number.isFinite(stock_minimo) || stock_minimo < 0) errores.push('stock_minimo no válido');
if (errores.length === 0 && cantidad > stock_minimo) {
  errores.push('incoherente: cantidad (' + cantidad + ') mayor que stock_minimo (' + stock_minimo + '), no requiere reposición');
}
if (errores.length) throw new Error('Entrada inválida en Alerta-Inventario-Trello: ' + errores.join('; '));

return {
  json: {
    producto, categoria, cantidad, stock_minimo,
    solicitud_id: String(j.solicitud_id ?? j.ticket ?? 'inventario-manual'),
    ticket: String(j.ticket ?? 'sin-ticket'),
    observacion: typeof j.observacion === 'string' ? j.observacion.trim().slice(0, 500) : ''
  }
};

// Clase 11: repetición / solicitud duplicada. No crear dos tarjetas abiertas del mismo producto.
const base = $('Validar Entrada Alerta').first().json;
const norm = s => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
const nombre = norm('Reposición urgente: ' + base.producto);
const duplicada = $input.all().some(i => norm(i.json.name) === nombre);
return [{ json: { ...base, duplicada } }];

