// Clase 09/11: la estructura válida no prueba que el contenido sea fiel. Se clasifica el estado.
const base = $('Detectar Duplicado').first().json;
const permitidas = ['reposicion', 'problema_proveedor', 'danio_o_perdida', 'otro'];
const r = $json;
const o = r.output;

let ia;
if (r.error || !o || typeof o !== 'object') {
  ia = { ia_estado: 'fallo_modelo_o_formato', ia_categoria: '', ia_resumen: '', ia_requiere_revision: true };
} else {
  const ok = permitidas.includes(o.categoria) &&
             typeof o.resumen === 'string' && o.resumen.trim() !== '' && o.resumen.length <= 300 &&
             typeof o.requiere_revision === 'boolean';
  if (!ok) {
    ia = { ia_estado: 'respuesta_no_valida', ia_categoria: '', ia_resumen: '', ia_requiere_revision: true };
  } else {
    ia = {
      ia_estado: o.requiere_revision ? 'revision_humana' : 'estructura_valida',
      ia_categoria: o.categoria,
      ia_resumen: o.resumen.trim(),
      ia_requiere_revision: o.requiere_revision
    };
  }
}
return { json: { ...base, ...ia } };

// Clase 11: la confirmación debe coincidir con el efecto real en Trello (id devuelto por el servicio).
const r = $json;
if (!r.id) throw new Error('Trello no devolvió el id de la tarjeta: no se puede confirmar la creación');
const base = $('Detectar Duplicado').first().json;
let ia_estado = 'sin_observacion';
try { ia_estado = $('Comprobar Respuesta IA').first().json.ia_estado ?? 'sin_observacion'; } catch (e) {}
return {
  json: {
    resultado: 'creada',
    producto: base.producto,
    ticket: base.ticket,
    solicitud_id: base.solicitud_id,
    ia_estado,
    trello_card_id: r.id,
    trello_url: r.shortUrl ?? ''
  }
};

// Rama de error de la alerta (antes la cubría el subworkflow + onError del Execute Workflow).
const base = $('Loop Over Items').first().json;
const e = $json.error;
const redactar = t => String(t).replace(/(oauth_token|oauth_consumer_key|token|key|apikey|api_key|authorization|password)(["'=:\s]+)[^\s"',;&]+/gi, '$1$2[REDACTADO]').replace(/Bearer\s+\S+/gi, 'Bearer [REDACTADO]').replace(/[A-Za-z0-9_\-]{32,}/g, '[REDACTADO]');
const msg = redactar(e?.message ?? e ?? 'Sin mensaje de error').slice(0, 500);
const m = msg.toLowerCase();
let tipo = 'fallo_alerta_trello';
if (/entrada inv/.test(m)) tipo = 'rechazo_por_validacion';
else if (/429|rate limit|quota|cuota/.test(m)) tipo = 'cuota_ia_o_api';
else if (/timeout|timed out|etimedout|econn|enotfound|502|503|504|service unavailable/.test(m)) tipo = 'dependencia_no_disponible';
else if (/401|403|unauthorized|forbidden|credential|permission/.test(m)) tipo = 'credencial_o_permisos';
return { json: {
  producto: base.producto ?? null,
  solicitud_id: base.solicitud_id ?? null,
  detalle: msg,
  tipo,
  fecha_hora: $now.toFormat('yyyy-MM-dd HH:mm:ss')
} };

// Contrato: producto = texto de 1 a 60 caracteres, sin caracteres de control.
const raw = $json.producto;
const norm = s => String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
const valido = typeof raw === 'string' && raw.trim().length > 0 && raw.trim().length <= 60 && !/[\u0000-\u001f]/.test(raw);
return { json: { entrada_valida: valido, producto_buscado: valido ? raw.trim() : null, busqueda: valido ? norm(raw) : null } };

const entrada = $('Validar Entrada Consulta').first().json;
const origen = 'Google Sheets · Inventario · Hoja 1';
const filas = $input.all().map(i => i.json);
const vacio = estado => ({ estado, encontrado: false, producto: entrada.producto_buscado, categoria: null,
                            cantidad: null, stock_minimo: null, necesita_reposicion: null, origen });

if (filas.some(f => f.error)) return [{ json: vacio('no_disponible') }];

const norm = s => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
const validas = filas.filter(f => f.producto !== undefined && norm(f.producto) !== '');
const exactas = validas.filter(f => norm(f.producto) === entrada.busqueda);
const coincidencias = exactas.length ? exactas : validas.filter(f => norm(f.producto).includes(entrada.busqueda));

if (coincidencias.length === 0) return [{ json: vacio('no_encontrado') }];
if (coincidencias.length > 1) {
  return [{ json: { ...vacio('coincidencias_multiples'), candidatos: coincidencias.slice(0, 5).map(f => String(f.producto).trim()) } }];
}

const f = coincidencias[0];
const cantidad = (f.cantidad === '' || f.cantidad == null) ? NaN : Number(f.cantidad);
const minimo = (f.stock_minimo === '' || f.stock_minimo == null) ? NaN : Number(f.stock_minimo);
if (!Number.isFinite(cantidad) || cantidad < 0) {
  return [{ json: { ...vacio('dato_inconsistente'), producto: String(f.producto).trim(), categoria: String(f.categoria ?? '').trim() } }];
}
return [{ json: {
  estado: 'consultado',
  encontrado: true,
  producto: String(f.producto).trim(),
  categoria: String(f.categoria ?? '').trim(),
  cantidad,
  stock_minimo: Number.isFinite(minimo) ? minimo : null,
  necesita_reposicion: Number.isFinite(minimo) ? cantidad <= minimo : null,
  origen
} }];

// Clase 11: distinguir rechazo por validación vs fallo técnico y dejar un estado localizable.
const e = $json.execution?.error ?? {};
const redactar = t => String(t).replace(/(oauth_token|oauth_consumer_key|token|key|apikey|api_key|authorization|password)(["'=:\s]+)[^\s"',;&]+/gi, '$1$2[REDACTADO]').replace(/Bearer\s+\S+/gi, 'Bearer [REDACTADO]').replace(/[A-Za-z0-9_\-]{32,}/g, '[REDACTADO]');
const msg = redactar(e.message ?? 'Sin mensaje de error').slice(0, 500);
const m = msg.toLowerCase();

let tipo = 'fallo_tecnico';
if (/entrada inv|dato inv|solicitud inv/.test(m)) tipo = 'rechazo_por_validacion';
else if (/429|quota|cuota|rate limit|resource_exhausted/.test(m)) tipo = 'cuota_ia_o_api';
else if (/timeout|timed out|etimedout|econn|enotfound|502|503|504|service unavailable/.test(m)) tipo = 'dependencia_no_disponible';
else if (/401|403|unauthorized|forbidden|credential|permission/.test(m)) tipo = 'credencial_o_permisos';

return {
  json: {
    fecha_hora: $now.toFormat('yyyy-MM-dd HH:mm:ss'),
    workflow: $json.workflow?.name ?? 'desconocido',
    nodo: $json.execution?.lastNodeExecuted ?? 'desconocido',
    mensaje: msg,
    ejecucion: String($json.execution?.id ?? 'sin_id'),
    tipo,
    estado: 'pendiente_revision',
    url_ejecucion: $json.execution?.url ?? ''
  }
};
